/* @autogenerated */
import { Component, computed, effect, input, OnDestroy, output, Signal, signal } from '@angular/core';
import { Router, RouterModule } from '@angular/router';
import { configValue } from '@shared/context/config/app-config.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatIconModule } from '@angular/material/icon';
import { MatListModule } from '@angular/material/list';
import { MatDividerModule } from '@angular/material/divider';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { NavItem } from 'app/bootstrap/workspace/workspace.model';
import { WorkspaceStateService } from 'app/bootstrap/workspace/workspace-state.service';
import { RouteAccessService } from 'app/bootstrap/layout/menu/route-accessible.service';
import { RuntimeThemeService } from '@shared/context/theme/runtime-theme.service';

@Component({
  selector: 'app-menu',
  standalone: true,
  imports: [CommonModule, RouterModule, MatButtonModule, MatDividerModule, MatIconModule, MatListModule, MatMenuModule],
  templateUrl: './menu.component.html',
  styleUrl: './menu.component.scss',
  host: { '[class.mini]': "mode() === 'mini'" },
})
export class MenuComponent implements OnDestroy {
  select = output<NavItem>();
  mode = input<string>('full');
  items = input<NavItem[] | undefined>();
  title: Signal<string | undefined>;
  logo: Signal<string>;
  productName: Signal<string>;
  currentLanguage: Signal<string>;
  currentTenant: Signal<string>;

  private subscriptions = new Subscription();
  private menuItems = signal<any[]>([]);
  private contextRedirectPending = false;
  private contextRedirectQueue: string[][] = [];
  private pendingContextTransition?: {
    previousPresence: Record<string, boolean>;
    currentPresence: Record<string, boolean>;
    items: NavItem[];
    activePath?: NavItem[];
  };
  private contextTransitionTimer?: ReturnType<typeof setTimeout>;

  menu = computed(() => this.menuItems());

  public constructor(
    private readonly appstate: AppStateService,
    private readonly router: Router,
    private readonly identity: IdentityService,
    private readonly checker: RouteAccessService,
    private readonly workspace: WorkspaceStateService,
    theme: RuntimeThemeService,
  ) {
    this.title = configValue('meta.title');
    this.logo = theme.logo;
    this.productName = theme.productName;
    this.currentLanguage = appstate.language;
    this.currentTenant = appstate.tenant;

    const user = appstate.user('main');
    let previousContextPresence: Record<string, boolean> | undefined;
    let previousContextScope: string | undefined;
    effect((onCleanup) => {
      const items = this.items();
      // Los guards dependen del usuario: al iniciar o cerrar sesión se vuelve a calcular la visibilidad
      user();
      // Las entradas con `requires` dependen de los selectores del contexto
      const contexts = this.appstate.contexts();
      const contextPresence = Object.fromEntries(
        Object.keys(contexts)
          .sort()
          .map((key) => [key, present(contexts[key]?.value)]),
      ) as Record<string, boolean>;
      const contextScope = this.appstate.contextScope();
      const previousPresence = previousContextPresence;
      const contextChanged =
        previousPresence !== undefined &&
        previousContextScope === contextScope &&
        JSON.stringify(previousPresence) !== JSON.stringify(contextPresence);
      previousContextPresence = contextPresence;
      previousContextScope = contextScope;
      const result = [] as any[];
      const navItems = items ?? [];
      const sub = new Subscription();
      if (items) {
        items.forEach((item) => {
          result.push(this.copyItem(item, contexts, undefined, sub));
        });
      }
      if (contextChanged) {
        this.pendingContextTransition ??= {
          previousPresence: previousPresence!,
          currentPresence: contextPresence,
          items: navItems,
          activePath: this.pathForActiveRoute(navItems),
        };
        this.pendingContextTransition.currentPresence = contextPresence;
        if (this.contextTransitionTimer !== undefined) {
          clearTimeout(this.contextTransitionTimer);
        }
        this.contextTransitionTimer = setTimeout(() => this.flushContextTransition(), 0);
      }
      this.menuItems.set(result);
      onCleanup(() => {
        sub.unsubscribe();
      });
    });
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    if (this.contextTransitionTimer !== undefined) {
      clearTimeout(this.contextTransitionTimer);
    }
  }

  public run(item: NavItem, event: any): void {
    this.select.emit(item);
    if (item.route) {
      this.router.navigate(this.workspace.link(item.route));
    }
  }

  public idioma(label: string): void {
    this.appstate.language.set(label);
  }

  public tenant(name: string): void {
    this.appstate.tenant.set(name);
  }

  public login(): void {
    this.identity.login('main');
  }

  public logout(): void {
    this.identity.logout('main');
  }

  private childsVisibility(item: any) {
    // Un grupo se ve si está disponible (sus `requires` tienen valor) y alguna de sus entradas se ve
    item.hidden = !item.available || !item.childs.find((i: any) => !i.hidden);
    item.active = item.childs.find((i: any) => i.active);
  }

  private copyItem(item: NavItem, contexts: Record<string, any>, parent?: any, sub?: Subscription) {
    // Sin los selectores que exige (ella o su grupo), la entrada no se muestra aunque los guards la permitan
    const available =
      (!parent || parent.available) &&
      (item.requires ?? []).every((key) => present(contexts[key]?.value)) &&
      (item.except ?? []).every((key) => !present(contexts[key]?.value));
    const copy = {
      label: item.label,
      icon: item.icon,
      route: item.route,
      available,
      hidden: !available,
      childs: [],
    } as any;

    if (item.route) {
      const url = this.workspace.url(item.route);
      copy.active = this.checker.isUrlActive(url);
      (sub || this.subscriptions).add(
        this.checker.checkRouteGuards(url).subscribe((res: any) => {
          copy.hidden = !available || res !== true;
          if (parent) {
            this.childsVisibility(parent);
          }
        }),
      );
      (sub || this.subscriptions).add(
        this.router.events.subscribe(() => {
          copy.active = this.checker.isUrlActive(url);
          if (parent) {
            this.childsVisibility(parent);
          }
        }),
      );
    }
    if (item.children) {
      item.children.forEach((sitem) => {
        copy.childs.push(this.copyItem(sitem, contexts, copy, sub));
      });
    }
    if (!item.route) {
      this.childsVisibility(copy);
    }
    return copy;
  }

  /** Espera a que terminen los efectos que limpian selectores dependientes y resuelve el cambio como una sola cadena. */
  private flushContextTransition(): void {
    this.contextTransitionTimer = undefined;
    const transition = this.pendingContextTransition;
    this.pendingContextTransition = undefined;
    if (!transition) {
      return;
    }
    const chain = this.redirectChain(
      transition.items,
      transition.previousPresence,
      transition.currentPresence,
      transition.activePath,
    );
    if (chain.length) {
      this.contextRedirectQueue.push(chain);
      this.runNextContextRedirect();
    }
  }

  /** Sigue los destinos de cada sección afectada, comenzando por la ruta activa. */
  private redirectChain(
    items: NavItem[],
    previousPresence: Record<string, boolean>,
    currentPresence: Record<string, boolean>,
    activePath?: NavItem[],
  ): string[] {
    if (!activePath) {
      return [];
    }
    const targets: string[] = [];
    const seen = new Set<string>();
    let path: NavItem[] | undefined = activePath;
    const activeRoute = path.at(-1)?.route;
    if (activeRoute) {
      seen.add(activeRoute);
    }
    while (path) {
      let target: string | undefined;
      for (let index = path.length - 1; index >= 0 && !target; index--) {
        target = this.hiddenTarget(path[index], previousPresence, currentPresence);
      }
      if (!target || seen.has(target)) {
        break;
      }
      targets.push(target);
      seen.add(target);
      path = this.pathForRoute(items, target);
    }
    return targets;
  }

  private pathForActiveRoute(items: NavItem[], parents: NavItem[] = []): NavItem[] | undefined {
    for (const item of items) {
      const path = [...parents, item];
      if (item.route && this.checker.isUrlActive(this.workspace.url(item.route))) {
        return path;
      }
      const childPath = item.children ? this.pathForActiveRoute(item.children, path) : undefined;
      if (childPath) {
        return childPath;
      }
    }
    return undefined;
  }

  private pathForRoute(items: NavItem[], route: string, parents: NavItem[] = []): NavItem[] | undefined {
    for (const item of items) {
      const path = [...parents, item];
      if (item.route === route) {
        return path;
      }
      const childPath = item.children ? this.pathForRoute(item.children, route, path) : undefined;
      if (childPath) {
        return childPath;
      }
    }
    return undefined;
  }

  /** Serializa la cadena para que cada destino se resuelva antes de navegar al siguiente. */
  private runNextContextRedirect(): void {
    if (this.contextRedirectPending || !this.contextRedirectQueue.length) {
      return;
    }
    const [target, ...remaining] = this.contextRedirectQueue.shift()!;
    if (this.checker.isUrlActive(this.workspace.url(target))) {
      if (remaining.length) {
        this.contextRedirectQueue.unshift(remaining);
      }
      this.runNextContextRedirect();
      return;
    }
    this.contextRedirectPending = true;
    Promise.resolve(this.router.navigate(this.workspace.link(target))).then(
      () => {
        this.contextRedirectPending = false;
        if (remaining.length) {
          this.contextRedirectQueue.unshift(remaining);
        }
        this.runNextContextRedirect();
      },
      () => {
        this.contextRedirectPending = false;
        if (remaining.length) {
          this.contextRedirectQueue.unshift(remaining);
        }
        this.runNextContextRedirect();
      },
    );
  }

  private hiddenTarget(
    item: NavItem,
    previousPresence: Record<string, boolean>,
    currentPresence: Record<string, boolean>,
  ): string | undefined {
    const requires = item.requires ?? [];
    const lostRequired = requires.some((key) => previousPresence[key] && !currentPresence[key]);
    const lostAllRequired =
      requires.length > 0 &&
      requires.some((key) => previousPresence[key]) &&
      requires.every((key) => !currentPresence[key]);
    if (lostAllRequired && item.goOnNoRequired) {
      return item.goOnNoRequired;
    }
    if (lostRequired) {
      return item.goOnUnrequired;
    }
    const except = item.except ?? [];
    if (except.length && except.every((key) => !previousPresence[key]) && except.some((key) => currentPresence[key])) {
      return item.goOnExcept;
    }
    return undefined;
  }
}

function present(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}
